INSERT INTO `applications` (`application_id`, `applicant_id`, `application_type`, `status`, `bot_verified`, `bot_score`, `bot_notes`, `assigned_officer`, `application_reason`, `marital_status`, `service_type`, `remarks`, `submitted_at`) VALUES (1, 1, 'New', 'Pending', 1, 95, 'Automated Bot Check: PASSED (Match Score: 95\%). Official Birth Certificate confirmed for Thilina Sakalasooriya.\n• Specimen Document: birthcerificate.pdf (Official Register of Births, Sri Lanka)\n• PDF Recorded Name: \"Thilina Srimal Sakalasooriya\" -> Applicant Name: \"Thilina Sakalasooriya\" (100\% match)\n• PDF Recorded Birth Date: 2005 May 31 (2005-05-31) -> Applicant DOB: \"2005-03-31\" (85\% match)\n• PDF Recorded Sex: Male -> Applicant Gender: \"Male\" (100\% match)\n• PDF Administrative Jurisdiction: District: Gampaha | Division: Ragama\n• Document Authenticity: 100\% Verified (Sri Lanka official registrar formatting, legal headings, and security criteria validated).', NULL, 'G.C.E O/L', 'Single', 'Normal', 'Fast-Track Approved by thilinapak. Validated by AI Bot Verification Engine (Score: 95\%).', '2026-09-15 10:14:24') ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);
INSERT INTO `applications` (`application_id`, `applicant_id`, `application_type`, `status`, `bot_verified`, `bot_score`, `bot_notes`, `assigned_officer`, `application_reason`, `marital_status`, `service_type`, `remarks`, `submitted_at`) VALUES (2, 2, 'New', 'Printed', 0, 62, 'Automated Bot Check: INCONCLUSIVE (Match Score: 62\%). Below 80\% threshold.\n• Specimen Document: birth_certificate.pdf\n• Discrepancies detected between submitted data (\"KULASINGHA GAMAGE NADUN NIMESH\", DOB: \"2002-01-04\") and official register details (\"Thilina Srimal Sakalasooriya\", DOB: \"2005 May 31\"). Forwarded for human officer review.', 'thilinapak', 'G.C.E O/L', 'Single', 'Normal', 'New citizen online submission.', '2026-09-15 13:00:50') ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);
INSERT INTO `applications` (`application_id`, `applicant_id`, `application_type`, `status`, `bot_verified`, `bot_score`, `bot_notes`, `assigned_officer`, `application_reason`, `marital_status`, `service_type`, `remarks`, `submitted_at`) VALUES (3, 3, 'New', 'Documents-Required', 0, 63, 'Automated Bot Check: INCONCLUSIVE (Match Score: 63\%). Below 80\% threshold.\n• Specimen Document: birthcerificate.pdf\n• Discrepancies detected between submitted data (\"Nimesh namnugama\", DOB: \"2004-02-03\") and official register details (\"Thilina Srimal Sakalasooriya\", DOB: \"2005 May 31\"). Forwarded for human officer review.', 'Officer Wickramasinghe', 'Wallet Got Stolen', 'Single', '1-Day', '[Action Required: Re-upload Birth Certificate] [Action Required: Re-upload Birth Certificate] New citizen online submission.', '2026-09-15 14:15:45') ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);
